namespace Veronica.Editing;

// Prefab templates are named by their browser path, e.g. "Blocks/Breakable/Ion Thrusters".
public static class Templates
{
    public const int MaxListed = 50;

    // Templates the Editor lacks, each generated by a vanilla template and finished by a recipe in TemplateRepairs.
    public static readonly IReadOnlyDictionary<string, SyntheticTemplate> Synthetic = new Dictionary<string, SyntheticTemplate>(StringComparer.OrdinalIgnoreCase)
    {
        ["Blocks/Breakable/Atmospheric Thrusters"] = new("Blocks/Breakable/Ion Thrusters", new Dictionary<string, string>
        {
            ["_IonThrusterDefinition"] = "_ThrusterDefinition",
            ["_IonThrusters_ThrusterEffectsComponentDefinition"] = "_Thrusters_ThrusterEffectsComponentDefinition",
        }),
    };

    public static string BaseOf(string template) => Synthetic.TryGetValue(template, out var synthetic) ? synthetic.Source : template;

    public static void AddSynthetic<T>(Dictionary<string, T> templates)
    {
        foreach (var (path, synthetic) in Synthetic)
        {
            if (templates.TryGetValue(synthetic.Source, out var value))
                templates.TryAdd(path, value);
        }
    }

    // A generated file named after the source template's family would mislead a model reading the file list.
    public static string FileStem(string template, string stem)
    {
        if (!Synthetic.TryGetValue(template, out var synthetic))
            return stem;
        string? from = synthetic.Renames.Keys.Where(k => stem.EndsWith(k, StringComparison.Ordinal)).MaxBy(k => k.Length);
        return from is null ? stem : stem[..^from.Length] + synthetic.Renames[from];
    }

    // The first tier with any match wins: exact path, exact last segment, every word present.
    public static List<string> Resolve(IEnumerable<string> templates, string query)
    {
        string[] wanted = Words(query);
        if (wanted.Length == 0)
            return [];

        var all = templates.ToList();
        var exact = all.Where(t => Words(t).SequenceEqual(wanted)).ToList();
        if (exact.Count > 0)
            return exact;

        var leaf = all.Where(t => Words(LastSegment(t)).SequenceEqual(wanted)).ToList();
        if (leaf.Count > 0)
            return leaf;

        return Sorted(all.Where(t => wanted.All(Words(t).Contains)));
    }

    // Discovery is looser than create_prefab: a filter word only has to be part of the path ("thrust").
    public static List<string> Filter(IEnumerable<string> templates, string? filter)
    {
        string[] wanted = Words(filter ?? "");
        return Sorted(templates.Where(t => wanted.All(w => t.Contains(w, StringComparison.OrdinalIgnoreCase))));
    }

    private static List<string> Sorted(IEnumerable<string> templates) =>
        templates.OrderBy(t => t, StringComparer.OrdinalIgnoreCase).ToList();

    private static string[] Words(string text) =>
        text.Split(['/', '\\', ' ', '\t'], StringSplitOptions.RemoveEmptyEntries).Select(w => w.ToLowerInvariant()).ToArray();

    private static string LastSegment(string path) => path[(path.LastIndexOfAny(['/', '\\']) + 1)..];
}

// Generated by the source template, then finished by its recipe; Renames maps generated file name endings to the family's own.
public sealed record SyntheticTemplate(string Source, IReadOnlyDictionary<string, string> Renames);
